// Adaptive dual contouring, bottom-up as in Ju et al. 2002: the uniform leaves and their
// Hermite data are computed first, then a node is collapsed into one leaf when its children
// are leaves, its pruned tree is a single primitive (or any tree, with the general option),
// the quadric summed over the children fits one vertex within the tolerance, and the sign
// samples of the children keep the topology of the node (one crossing at most per edge, no
// inner sheet lost, one component). The quads are generated by the cell, face and edge
// recursion, which is crack free for leaves of different sizes.
//
// With top_down the coarse leaves are decided while the octree is built instead: a cell whose
// pruned tree is a single primitive (or any tree, with the general option) is probed on the grid
// of the finest level inside it (2^(max_depth - level) subcells per axis), and when the probe
// passes the same tests (one crossing at most per edge, no inner sheet, one component in the cell
// and in every subcell, one vertex within the tolerance for the quadric of the crossings) the
// cell becomes a leaf, and the octree below it, its tables and its leaves are never built. A
// coarser probe misses features smaller than its spacing, such as rounded box edges. The
// bottom-up collapse only finds the corner values of a node among those of the finest leaves,
// which exist next to the surface only, so it never merges more than one level.
#pragma once
#include <omp.h>

#include <Eigen/Dense>
#include <algorithm>
#include <array>
#include <parallel/algorithm>
#include <cstdint>
#include <unordered_map>
#include <vector>

#include "lpm/dc.h"

namespace lpm {

struct AdaptiveParams {
    int max_depth = 8;
    int min_depth = 2;              // never collapse above this depth
    double tol = 0.02;              // residual of the quadric (distance of the vertex to the tangent planes), relative to the cell size
    bool single_primitive_only = true;  // collapse only where the pruned tree is one primitive
    double margin = 1e-3;
    bool top_down = false;          // coarse leaves decided during the build (see above)
};

struct AdaptiveStats {
    std::vector<uint64_t> leaves_per_level;
    uint64_t fine_leaves = 0, leaves = 0, vertices = 0, triangles = 0, collapsed = 0;
    double t_octree = 0, t_hermite = 0, t_collapse = 0, t_faces = 0, total = 0;
};

namespace adetail {
static const int edge_corners[12][2] = {{0, 1}, {2, 3}, {4, 5}, {6, 7}, {0, 2}, {1, 3}, {4, 6}, {5, 7}, {0, 4}, {1, 5}, {2, 6}, {3, 7}};
inline int local_edge(int axis, int bx, int by, int bz) {
    const int bits[3] = {bx, by, bz};
    const int B = axis == 0 ? 1 : 0, C = axis == 2 ? 1 : 2;
    return 4 * axis + bits[B] + 2 * bits[C];
}
inline void others(int axis, int& first, int& second) {
    static const int O[3][2] = {{1, 2}, {2, 0}, {0, 1}};
    first = O[axis][0]; second = O[axis][1];
}
struct Quadric {
    Eigen::Matrix3d ATA = Eigen::Matrix3d::Zero();
    Eigen::Vector3d ATb = Eigen::Vector3d::Zero(), mass = Eigen::Vector3d::Zero();
    double btb = 0.0;
    int count = 0;
    void add(const double p[3], const double n[3]) {
        Eigen::Vector3d nn(n[0], n[1], n[2]), pp(p[0], p[1], p[2]);
        const double b = nn.dot(pp);
        ATA += nn * nn.transpose(); ATb += nn * b; btb += b * b; mass += pp; count++;
    }
    void add(const Quadric& o) { ATA += o.ATA; ATb += o.ATb; btb += o.btb; mass += o.mass; count += o.count; }
    // Minimizer clamped to the box, and the root mean square distance to the planes.
    Eigen::Vector3d solve(const double lo[3], const double hi[3], double* residual) const {
        Eigen::Vector3d m = mass / std::max(count, 1);
        Eigen::SelfAdjointEigenSolver<Eigen::Matrix3d> es(ATA);
        const Eigen::Vector3d ev = es.eigenvalues();
        const double lmax = ev.maxCoeff();
        Eigen::Matrix3d pinv = Eigen::Matrix3d::Zero();
        for (int k = 0; k < 3; k++) if (ev[k] > 1e-2 * lmax && ev[k] > 1e-12) { const Eigen::Vector3d v = es.eigenvectors().col(k); pinv += v * v.transpose() / ev[k]; }
        Eigen::Vector3d x = m + pinv * (ATb - ATA * m);
        for (int a = 0; a < 3; a++) x[a] = std::min(std::max(x[a], lo[a]), hi[a]);
        if (residual) *residual = std::sqrt(std::max(0.0, (x.dot(ATA * x) - 2.0 * x.dot(ATb) + btb) / std::max(count, 1)));
        return x;
    }
};
// Keeps in slot the smaller of its value and v (owners as (tree size << 32) | cell index: the
// smallest tree, the first cell on ties, as the serial loop).
inline void atomic_min(uint64_t& slot, uint64_t v) {
    uint64_t cur = __atomic_load_n(&slot, __ATOMIC_RELAXED);
    while (v < cur && !__atomic_compare_exchange_n(&slot, &cur, v, true, __ATOMIC_RELAXED, __ATOMIC_RELAXED)) {}
}
}  // namespace adetail

class AdaptiveMesher {
public:
    AdaptiveMesher(const Scene& scene, const AdaptiveParams& params, const DCParams& dc) : scene_(scene), p_(params), dc_(dc) {}

    Mesh run(Counters& counters, AdaptiveStats& st) {
        Timer total;
        OctreeParams op;
        op.oracle = ORACLE_LIPSCHITZ;
        op.max_depth = p_.max_depth;
        op.margin = p_.margin;
        D_ = p_.max_depth;
        if (p_.top_down) {
            build_top_down(op, counters);
        } else {
            oct_ = build_octree(scene_, op, counters);
        }
        st.t_octree = oct_.build_seconds;
        Timer th;
        hermite(counters);
        st.t_hermite = th.seconds();
        st.fine_leaves = leaves_.size();
        Timer tc;
        if (p_.top_down) {
            // The coarse leaves of the build join the leaves of the finest level.
            leaves_.reserve(leaves_.size() + coarse_.size());
            for (const Coarse& c : coarse_) {
                leaf_of_[c.leaf.level][c.cell] = (int32_t)leaves_.size();
                leaves_.push_back(c.leaf);
            }
            st.collapsed = coarse_.size();
        } else {
            collapse(st);
        }
        st.t_collapse = tc.seconds();
        Timer tf;
        // Vertices of the surviving leaves.
        vbase_.assign(leaves_.size(), 0);
        for (size_t i = 0; i < leaves_.size(); i++) {
            const Leaf& L = leaves_[i];
            if (!L.alive) continue;
            vbase_[i] = (uint32_t)(mesh_.V.size() / 3);
            for (int q = 0; q < L.ncomp; q++) { for (int a = 0; a < 3; a++) mesh_.V.push_back(L.v[q][a]); mesh_.tree_n.push_back(L.tree_n); }
        }
        st.leaves_per_level.assign(D_ + 1, 0);
        for (const Leaf& L : leaves_) if (L.alive) { st.leaves_per_level[L.level]++; st.leaves++; }
        cell_proc(0, 0);
        st.t_faces = tf.seconds();
        st.vertices = mesh_.V.size() / 3;
        st.triangles = mesh_.F.size() / 3;
        st.total = total.seconds();
        return std::move(mesh_);
    }

private:
    struct Leaf {
        uint32_t x, y, z;
        uint8_t level;
        bool alive = true;
        uint32_t tree_n = 0;
        double f[8];
        int8_t comp[12];
        uint8_t ncomp = 0;
        double v[6][3];
    };
    // Quadrics of the components of each leaf (same index as leaves_), for the bottom-up collapse
    // only: kept out of Leaf, which a million leaves copy around.
    std::vector<std::array<adetail::Quadric, 6>> quads_;
    const Scene& scene_;
    AdaptiveParams p_;
    DCParams dc_;
    Octree oct_;
    int D_ = 0;
    std::vector<Leaf> leaves_;
    std::vector<std::vector<int32_t>> leaf_of_;   // per level: leaf index of each octree cell, -1 if internal
    std::vector<std::vector<std::array<int32_t, 8>>> children_;  // per level: children of each cell (index in next level), -1 if absent
    std::vector<uint32_t> vbase_;
    std::vector<std::vector<uint32_t>> cell_corner_;  // per level: 8 fine corner indices of each cell
    std::vector<uint64_t> ckeys_;
    std::vector<double> cval_;
    Mesh mesh_;
    struct Coarse { uint32_t cell; Leaf leaf; };  // top-down: a coarse leaf and its index in its level
    std::vector<Coarse> coarse_;

    // Top-down build: build_octree for the Lipschitz oracle, where a cell that passes probe()
    // becomes a leaf of its level and gets no children.
    void build_top_down(const OctreeParams& params, Counters& counters) {
        Timer total;
        oct_ = Octree{};
        oct_.scene = &scene_;
        oct_.params = params;
        oct_.full = full_tree(scene_);
        const int nthreads = omp_get_max_threads();
        {
            Level L0;
            for (int a = 0; a < 3; a++) L0.size[a] = scene_.aabb_max[a] - scene_.aabb_min[a];
            Cell root{0, 0, 0};
            double c[3], R = 0.0;
            for (int a = 0; a < 3; a++) { c[a] = scene_.aabb_min[a] + 0.5 * L0.size[a]; R += 0.25 * L0.size[a] * L0.size[a]; }
            R = std::sqrt(R);
            Scratch sc;
            root.value = prune_lipschitz(scene_, TreeView{oct_.full.data(), (uint32_t)oct_.full.size()}, c, R * (1.0 + params.margin), L0.pool,
                                         root.tree_n, sc, counters);
            L0.tested = 1;
            L0.sum_tree_n = L0.max_tree_n = root.tree_n;
            L0.single_prim = root.tree_n == 1;
            L0.cells.push_back(root);
            oct_.levels.push_back(std::move(L0));
        }
        std::vector<uint8_t> stop(1, 0);  // per cell of the last level: it is a coarse leaf
        for (int depth = 1; depth <= D_; depth++) {
            Timer lt;
            const Level& parent = oct_.levels[depth - 1];
            Level L;
            for (int a = 0; a < 3; a++) L.size[a] = parent.size[a] * 0.5;
            const double R = 0.5 * std::sqrt(L.size[0] * L.size[0] + L.size[1] * L.size[1] + L.size[2] * L.size[2]);
            std::vector<std::vector<Cell>> cells_t(nthreads);
            std::vector<std::vector<TreeEntry>> pool_t(nthreads);
            std::vector<Counters> cnt_t(nthreads);
            std::vector<uint64_t> tested_t(nthreads, 0);
#pragma omp parallel
            {
                const int tid = omp_get_thread_num();
                Scratch sc;
#pragma omp for schedule(dynamic, 16)
                for (size_t pi = 0; pi < parent.cells.size(); pi++) {
                    if (stop[pi]) continue;
                    const Cell& pc = parent.cells[pi];
                    const TreeView in = oct_.tree_of(depth - 1, pc);
                    for (int child = 0; child < 8; child++) {
                        Cell cc;
                        cc.x = 2 * pc.x + (child & 1);
                        cc.y = 2 * pc.y + ((child >> 1) & 1);
                        cc.z = 2 * pc.z + ((child >> 2) & 1);
                        const uint32_t idx[3] = {cc.x, cc.y, cc.z};
                        double c[3];
                        for (int a = 0; a < 3; a++) c[a] = scene_.aabb_min[a] + (idx[a] + 0.5) * L.size[a];
                        tested_t[tid]++;
                        std::vector<TreeEntry>& pool = pool_t[tid];
                        const size_t base = pool.size();
                        const double d = prune_lipschitz(scene_, in, c, R * (1.0 + params.margin), pool, cc.tree_n, sc, cnt_t[tid]);
                        if (std::fabs(d) <= R * (1.0 + 1e-9)) {
                            cc.value = d;
                            cc.tree_off = (uint32_t)base;
                            cells_t[tid].push_back(cc);
                        } else {
                            pool.resize(base);
                        }
                    }
                }
            }
            for (int t = 0; t < nthreads; t++) {
                const uint32_t off = (uint32_t)L.pool.size();
                for (Cell c : cells_t[t]) { c.tree_off += off; L.cells.push_back(c); }
                L.pool.insert(L.pool.end(), pool_t[t].begin(), pool_t[t].end());
                counters.add(cnt_t[t]);
                L.tested += tested_t[t];
            }
            std::sort(L.cells.begin(), L.cells.end(), [](const Cell& a, const Cell& b) { return cell_key(a.x, a.y, a.z) < cell_key(b.x, b.y, b.z); });
            for (const Cell& c : L.cells) {
                L.sum_tree_n += c.tree_n;
                L.max_tree_n = std::max<uint64_t>(L.max_tree_n, c.tree_n);
                if (c.tree_n == 1) L.single_prim++;
            }
            oct_.levels.push_back(std::move(L));
            // The coarse leaves of this level.
            const Level& cur = oct_.levels[depth];
            stop.assign(cur.cells.size(), 0);
            // The probe has the resolution of the finest level, up to 32 subcells per axis.
            if (depth >= std::max(p_.min_depth, D_ - 5) && depth < D_) {
                std::vector<std::vector<Coarse>> found_t(nthreads);
                std::vector<Counters> pcnt_t(nthreads);
#pragma omp parallel
                {
                    const int tid = omp_get_thread_num();
                    Scratch sc;
#pragma omp for schedule(dynamic, 64)
                    for (size_t i = 0; i < cur.cells.size(); i++) {
                        const Cell& c = cur.cells[i];
                        if (p_.single_primitive_only && c.tree_n != 1) continue;
                        Coarse co;
                        co.cell = (uint32_t)i;
                        if (probe(depth, c, co.leaf, sc, pcnt_t[tid])) { stop[i] = 1; found_t[tid].push_back(co); }
                    }
                }
                for (int t = 0; t < nthreads; t++) { for (Coarse& co : found_t[t]) coarse_.push_back(co); counters.add(pcnt_t[t]); }
            }
            oct_.levels[depth].seconds = lt.seconds();
        }
        // In the order of the cells, not of the threads that found them.
        std::sort(coarse_.begin(), coarse_.end(), [](const Coarse& a, const Coarse& b) {
            return a.leaf.level != b.leaf.level ? a.leaf.level < b.leaf.level : a.cell < b.cell;
        });
        oct_.build_seconds = total.seconds();
    }

    // Probe of a candidate coarse leaf on the P^3 cells of the finest level inside it: the tests of
    // the bottom-up collapse on its samples, and the leaf when they pass.
    bool probe(int level, const Cell& cell, Leaf& out, Scratch& sc, Counters& cnt) {
        const int P = 1 << (D_ - level), P1 = P + 1;
        const TreeView tree = oct_.tree_of(level, cell);
        double lo[3], hi[3];
        cell_bounds(level, cell.x, cell.y, cell.z, lo, hi);
        const double* size = oct_.levels[level].size;
        std::vector<double> s((size_t)P1 * P1 * P1);
        auto at = [&](int i, int j, int k) -> double& { return s[((size_t)i * P1 + j) * P1 + k]; };
        auto point = [&](int i, int j, int k, double p[3]) {
            const int g[3] = {i, j, k};
            for (int a = 0; a < 3; a++) p[a] = lo[a] + size[a] * g[a] / P;
        };
        for (int i = 0; i < P1; i++) for (int j = 0; j < P1; j++) for (int k = 0; k < P1; k++) {
            double p[3];
            point(i, j, k, p);
            at(i, j, k) = eval_tree(scene_, tree, p, sc, cnt);
        }
        auto in = [&](int i, int j, int k) { return at(i, j, k) < 0.0; };
        // Edges of the cell: one sign change at most along the samples.
        for (int e = 0; e < 12; e++) {
            const int c0 = adetail::edge_corners[e][0], c1 = adetail::edge_corners[e][1];
            int g0[3] = {(c0 & 1) * P, ((c0 >> 1) & 1) * P, ((c0 >> 2) & 1) * P};
            const int g1[3] = {(c1 & 1) * P, ((c1 >> 1) & 1) * P, ((c1 >> 2) & 1) * P};
            int axis = 0;
            for (int a = 0; a < 3; a++) if (g0[a] != g1[a]) axis = a;
            int changes = 0;
            bool prev = in(g0[0], g0[1], g0[2]);
            for (int t = 1; t <= P; t++) {
                g0[axis] = t;
                const bool b = in(g0[0], g0[1], g0[2]);
                changes += b != prev;
                prev = b;
            }
            if (changes > 1) return false;
        }
        // Faces whose corners share a sign, and the cube: every sample shares it.
        for (int axis = 0; axis < 3; axis++) for (int side = 0; side < 2; side++) {
            const int B = (axis + 1) % 3, C = (axis + 2) % 3;
            int g[3];
            g[axis] = side * P;
            bool sign = false, uniform = true, first = true;
            for (int u = 0; u <= P; u += P) for (int v = 0; v <= P; v += P) {
                g[B] = u; g[C] = v;
                const bool b = in(g[0], g[1], g[2]);
                if (first) { sign = b; first = false; } else if (b != sign) uniform = false;
            }
            if (!uniform) continue;
            for (int u = 0; u <= P; u++) for (int v = 0; v <= P; v++) { g[B] = u; g[C] = v; if (in(g[0], g[1], g[2]) != sign) return false; }
        }
        // The cell and every subcell: one component, no ambiguous face.
        auto simple = [&](int i0, int j0, int k0, int step, Leaf& L) {
            bool neg = false, pos = false;
            for (int k = 0; k < 8; k++) {
                L.f[k] = at(i0 + (k & 1) * step, j0 + ((k >> 1) & 1) * step, k0 + ((k >> 2) & 1) * step);
                (L.f[k] < 0.0 ? neg : pos) = true;
            }
            if (!(neg && pos)) { L.ncomp = 0; return true; }  // no crossing
            for (int axis = 0; axis < 3; axis++) for (int side = 0; side < 2; side++) {
                const int bx = (axis + 1) % 3, cx = (axis + 2) % 3, ob[4] = {0, 1, 1, 0}, oc[4] = {0, 0, 1, 1};
                int corners[4], nc = 0;
                for (int q = 0; q < 4; q++) corners[q] = (side << axis) | (ob[q] << bx) | (oc[q] << cx);
                for (int q = 0; q < 4; q++) nc += (L.f[corners[q]] < 0.0) != (L.f[corners[(q + 1) % 4]] < 0.0);
                if (nc == 4) return false;
            }
            Counters dummy;
            components(L, D_, TreeView{}, sc, dummy);  // no ambiguous face: no sample is needed
            return L.ncomp <= 1;
        };
        for (int i = 0; i < P; i++) for (int j = 0; j < P; j++) for (int k = 0; k < P; k++) {
            Leaf sub;
            if (!simple(i, j, k, 1, sub)) return false;
        }
        out = Leaf{};
        out.x = cell.x; out.y = cell.y; out.z = cell.z; out.level = (uint8_t)level; out.tree_n = cell.tree_n;
        if (!simple(0, 0, 0, P, out) || out.ncomp != 1) return false;
        // Quadric of the crossings of the probe edges, one vertex, residual.
        adetail::Quadric Q;
        // The step of the finest level (not built yet), as the finite differences of its leaves.
        const double fine = std::ldexp(1.0, level - D_);
        const double h = dc_.fd_rel * std::min(size[0] * fine, std::min(size[1] * fine, size[2] * fine));
        for (int axis = 0; axis < 3; axis++)
            for (int i = 0; i < P1; i++) for (int j = 0; j < P1; j++) for (int k = 0; k < P1; k++) {
                int g1[3] = {i, j, k};
                if (g1[axis] == P) continue;
                g1[axis]++;
                const double f0 = at(i, j, k), f1 = at(g1[0], g1[1], g1[2]);
                if ((f0 < 0.0) == (f1 < 0.0)) continue;
                double p0[3], p1[3], x[3], n[3];
                point(i, j, k, p0);
                point(g1[0], g1[1], g1[2], p1);
                bool converged;
                const double t = detail::edge_root(scene_, tree, p0, p1, f0, f1, dc_.max_iters, sc, cnt, 1e-12, &converged);
                for (int a = 0; a < 3; a++) x[a] = p0[a] + t * (p1[a] - p0[a]);
                detail::crossing_normal(scene_, tree, x, h, converged, axis, f0, n, sc, cnt);
                Q.add(x, n);
            }
        if (Q.count < 3) return false;
        double residual = 0.0;
        const Eigen::Vector3d v = Q.solve(lo, hi, &residual);
        if (residual > p_.tol * std::min(size[0], std::min(size[1], size[2]))) return false;
        for (int a = 0; a < 3; a++) out.v[0][a] = v[a];
        return true;
    }

    uint64_t N1() const { return (1ull << D_) + 1; }
    uint64_t corner_key(uint64_t x, uint64_t y, uint64_t z) const { return (x * N1() + y) * N1() + z; }
    void cell_bounds(int level, uint32_t x, uint32_t y, uint32_t z, double lo[3], double hi[3]) const {
        const Level& L = oct_.levels[level];
        const uint32_t idx[3] = {x, y, z};
        for (int a = 0; a < 3; a++) { lo[a] = scene_.aabb_min[a] + idx[a] * L.size[a]; hi[a] = lo[a] + L.size[a]; }
    }

    // Tree structure: children links and, for the finest level, the Hermite data of every leaf.
    void hermite(Counters& counters) {
        const int nthreads = omp_get_max_threads();
        children_.assign(D_ + 1, {});
        leaf_of_.assign(D_ + 1, {});
        for (int l = 0; l <= D_; l++) {
            children_[l].assign(oct_.levels[l].cells.size(), {-1, -1, -1, -1, -1, -1, -1, -1});
            leaf_of_[l].assign(oct_.levels[l].cells.size(), -1);
        }
        for (int l = 1; l <= D_; l++) {
            std::unordered_map<uint64_t, uint32_t> parents;
            parents.reserve(oct_.levels[l - 1].cells.size() * 2);
            for (uint32_t i = 0; i < oct_.levels[l - 1].cells.size(); i++) { const Cell& c = oct_.levels[l - 1].cells[i]; parents.emplace(cell_key(c.x, c.y, c.z), i); }
            for (uint32_t i = 0; i < oct_.levels[l].cells.size(); i++) {
                const Cell& c = oct_.levels[l].cells[i];
                auto it = parents.find(cell_key(c.x >> 1, c.y >> 1, c.z >> 1));
                children_[l - 1][it->second][(c.x & 1) | ((c.y & 1) << 1) | ((c.z & 1) << 2)] = (int32_t)i;
            }
        }
        const Level& L = oct_.levels[D_];
        const double* size = L.size;
        // Shared corner values of the finest cells.
        ckeys_.resize(L.cells.size() * 8);
        for (size_t i = 0; i < L.cells.size(); i++) for (int k = 0; k < 8; k++) ckeys_[8 * i + k] = corner_key(L.cells[i].x + (k & 1), L.cells[i].y + ((k >> 1) & 1), L.cells[i].z + ((k >> 2) & 1));
        __gnu_parallel::sort(ckeys_.begin(), ckeys_.end());
        ckeys_.erase(std::unique(ckeys_.begin(), ckeys_.end()), ckeys_.end());
        std::vector<uint32_t> cc(L.cells.size() * 8);
        std::vector<int32_t> owner(ckeys_.size(), -1);
        {
            std::vector<uint64_t> best(ckeys_.size(), UINT64_MAX);
#pragma omp parallel for schedule(static)
            for (size_t i = 0; i < L.cells.size(); i++) for (int k = 0; k < 8; k++) {
                const uint64_t key = corner_key(L.cells[i].x + (k & 1), L.cells[i].y + ((k >> 1) & 1), L.cells[i].z + ((k >> 2) & 1));
                const uint32_t u = (uint32_t)(std::lower_bound(ckeys_.begin(), ckeys_.end(), key) - ckeys_.begin());
                cc[8 * i + k] = u;
                adetail::atomic_min(best[u], ((uint64_t)L.cells[i].tree_n << 32) | (uint64_t)i);
            }
#pragma omp parallel for schedule(static)
            for (size_t u = 0; u < ckeys_.size(); u++) owner[u] = (int32_t)(best[u] & 0xffffffffu);
        }
        cval_.resize(ckeys_.size());
        std::vector<Counters> cnt_t(nthreads);
        auto point_of = [&](uint64_t key, double p[3]) {
            const uint64_t cz = key % N1(), cy = (key / N1()) % N1(), cx = key / (N1() * N1());
            p[0] = scene_.aabb_min[0] + cx * size[0]; p[1] = scene_.aabb_min[1] + cy * size[1]; p[2] = scene_.aabb_min[2] + cz * size[2];
        };
#pragma omp parallel
        {
            Scratch sc;
            Counters& cnt = cnt_t[omp_get_thread_num()];
#pragma omp for schedule(dynamic, 1024)
            for (size_t u = 0; u < ckeys_.size(); u++) { double p[3]; point_of(ckeys_[u], p); cval_[u] = eval_tree(scene_, oct_.tree_of(D_, L.cells[owner[u]]), p, sc, cnt); }
        }
        // Shared crossings.
        std::vector<uint64_t> ekeys;
        {
            std::vector<std::vector<uint64_t>> ek_t(nthreads);
#pragma omp parallel
            {
                std::vector<uint64_t>& ek = ek_t[omp_get_thread_num()];
#pragma omp for schedule(static)
                for (size_t i = 0; i < L.cells.size(); i++) for (int e = 0; e < 12; e++) {
                    const uint32_t c0 = cc[8 * i + adetail::edge_corners[e][0]], c1 = cc[8 * i + adetail::edge_corners[e][1]];
                    if ((cval_[c0] < 0.0) != (cval_[c1] < 0.0)) ek.push_back(ckeys_[c0] * 3 + (uint64_t)(e / 4));
                }
            }
            for (const std::vector<uint64_t>& ek : ek_t) ekeys.insert(ekeys.end(), ek.begin(), ek.end());
        }
        __gnu_parallel::sort(ekeys.begin(), ekeys.end());
        ekeys.erase(std::unique(ekeys.begin(), ekeys.end()), ekeys.end());
        std::vector<int32_t> eowner(ekeys.size(), -1);
        {
            std::vector<uint64_t> best(ekeys.size(), UINT64_MAX);
#pragma omp parallel for schedule(static)
            for (size_t i = 0; i < L.cells.size(); i++) for (int e = 0; e < 12; e++) {
                const uint32_t c0 = cc[8 * i + adetail::edge_corners[e][0]], c1 = cc[8 * i + adetail::edge_corners[e][1]];
                if ((cval_[c0] < 0.0) == (cval_[c1] < 0.0)) continue;  // only the crossing edges are keys
                const uint64_t key = ckeys_[c0] * 3 + (uint64_t)(e / 4);
                const size_t u = std::lower_bound(ekeys.begin(), ekeys.end(), key) - ekeys.begin();
                adetail::atomic_min(best[u], ((uint64_t)L.cells[i].tree_n << 32) | (uint64_t)i);
            }
#pragma omp parallel for schedule(static)
            for (size_t u = 0; u < ekeys.size(); u++) eowner[u] = (int32_t)(best[u] & 0xffffffffu);
        }
        std::vector<detail::Crossing> cross(ekeys.size());
#pragma omp parallel
        {
            Scratch sc;
            Counters& cnt = cnt_t[omp_get_thread_num()];
#pragma omp for schedule(dynamic, 256)
            for (size_t u = 0; u < ekeys.size(); u++) {
                const int axis = (int)(ekeys[u] % 3);
                const uint64_t k0 = ekeys[u] / 3;
                double p0[3], p1[3];
                point_of(k0, p0);
                for (int k = 0; k < 3; k++) p1[k] = p0[k];
                p1[axis] += size[axis];
                const TreeView tree = oct_.tree_of(D_, L.cells[eowner[u]]);
                const double f0 = cval_[std::lower_bound(ckeys_.begin(), ckeys_.end(), k0) - ckeys_.begin()];
                uint64_t k1 = k0 + (axis == 0 ? N1() * N1() : axis == 1 ? N1() : 1);
                const double f1 = cval_[std::lower_bound(ckeys_.begin(), ckeys_.end(), k1) - ckeys_.begin()];
                detail::Crossing& cr = cross[u];
                bool converged;
                const double tt = detail::edge_root(scene_, tree, p0, p1, f0, f1, dc_.max_iters, sc, cnt, 1e-12, &converged);
                for (int k = 0; k < 3; k++) cr.p[k] = p0[k] + tt * (p1[k] - p0[k]);
                const double h = dc_.fd_rel * std::min(size[0], std::min(size[1], size[2]));
                detail::crossing_normal(scene_, tree, cr.p, h, converged, axis, f0, cr.n, sc, cnt);
            }
        }
        // Leaves of the finest level: components, quadrics, vertices.
        leaves_.resize(L.cells.size());
        if (!p_.top_down) quads_.resize(L.cells.size());
        cell_corner_.assign(D_ + 1, {});
        cell_corner_[D_] = cc;
#pragma omp parallel
        {
            Scratch sc;
            Counters& cnt = cnt_t[omp_get_thread_num()];
#pragma omp for schedule(dynamic, 256)
            for (size_t i = 0; i < L.cells.size(); i++) {
                Leaf& Lf = leaves_[i];
                const Cell& c = L.cells[i];
                Lf.x = c.x; Lf.y = c.y; Lf.z = c.z; Lf.level = (uint8_t)D_; Lf.tree_n = c.tree_n;
                for (int k = 0; k < 8; k++) Lf.f[k] = cval_[cc[8 * i + k]];
                components(Lf, D_, oct_.tree_of(D_, c), sc, cnt);
                adetail::Quadric q6[6];
                for (int e = 0; e < 12; e++) {
                    const int q = Lf.comp[e];
                    if (q < 0) continue;
                    const uint32_t c0 = cc[8 * i + adetail::edge_corners[e][0]];
                    const size_t u = std::lower_bound(ekeys.begin(), ekeys.end(), ckeys_[c0] * 3 + (uint64_t)(e / 4)) - ekeys.begin();
                    q6[q].add(cross[u].p, cross[u].n);
                }
                double lo[3], hi[3];
                cell_bounds(D_, c.x, c.y, c.z, lo, hi);
                for (int q = 0; q < Lf.ncomp; q++) { Eigen::Vector3d x = q6[q].solve(lo, hi, nullptr); for (int a = 0; a < 3; a++) Lf.v[q][a] = x[a]; }
                if (!p_.top_down) for (int q = 0; q < 6; q++) quads_[i][q] = q6[q];
                leaf_of_[D_][i] = (int32_t)i;
            }
        }
        for (int t = 0; t < nthreads; t++) counters.add(cnt_t[t]);
    }

    // Components of the crossing edges of a leaf from its corner values; ambiguous faces are
    // decided by the sign at the face center (a fine corner value when available).
    void components(Leaf& L, int level, TreeView tree, Scratch& sc, Counters& cnt) {
        // Edge between two corners, -1 if none (built once, thread-safe).
        static const std::array<std::array<int, 8>, 8> edge_of = [] {
            std::array<std::array<int, 8>, 8> t;
            for (auto& row : t) row.fill(-1);
            for (int e = 0; e < 12; e++) { t[adetail::edge_corners[e][0]][adetail::edge_corners[e][1]] = e; t[adetail::edge_corners[e][1]][adetail::edge_corners[e][0]] = e; }
            return t;
        }();
        bool crossing[12];
        int any = 0;
        for (int e = 0; e < 12; e++) { crossing[e] = (L.f[adetail::edge_corners[e][0]] < 0.0) != (L.f[adetail::edge_corners[e][1]] < 0.0); any += crossing[e]; }
        for (int e = 0; e < 12; e++) L.comp[e] = -1;
        L.ncomp = 0;
        if (!any) return;
        int parent[12];
        for (int e = 0; e < 12; e++) parent[e] = e;
        auto find = [&](int e) { while (parent[e] != e) { parent[e] = parent[parent[e]]; e = parent[e]; } return e; };
        auto unite = [&](int a, int b) { a = find(a); b = find(b); if (a != b) parent[a] = b; };
        for (int axis = 0; axis < 3; axis++) {
            const int bx = (axis + 1) % 3, cx = (axis + 2) % 3;
            for (int side = 0; side < 2; side++) {
                int corners[4];
                const int ob[4] = {0, 1, 1, 0}, oc[4] = {0, 0, 1, 1};
                for (int q = 0; q < 4; q++) corners[q] = (side << axis) | (ob[q] << bx) | (oc[q] << cx);
                int fe[4], nc = 0;
                for (int q = 0; q < 4; q++) { fe[q] = edge_of[corners[q]][corners[(q + 1) % 4]]; nc += crossing[fe[q]]; }
                if (nc == 2) {
                    int first = -1;
                    for (int q = 0; q < 4; q++) if (crossing[fe[q]]) { if (first < 0) first = fe[q]; else unite(first, fe[q]); }
                } else if (nc == 4) {
                    const bool s0 = L.f[corners[0]] < 0.0;
                    bool sc_in;
                    if (level < D_) {
                        sc_in = sample_at(L, level, axis, side) < 0.0;  // the face center is a fine corner
                    } else {
                        // The level of the finest leaves exists by now: the probe of the top-down build,
                        // which runs before it is built, never reaches an ambiguous face.
                        const double* size = oct_.levels[level].size;
                        double center[3];
                        const uint32_t idx[3] = {L.x, L.y, L.z};
                        for (int a = 0; a < 3; a++) center[a] = scene_.aabb_min[a] + (idx[a] + 0.5) * size[a];
                        center[axis] = scene_.aabb_min[axis] + (idx[axis] + side) * size[axis];
                        sc_in = eval_tree(scene_, tree, center, sc, cnt) < 0.0;
                    }
                    if (sc_in == s0) { unite(fe[0], fe[1]); unite(fe[2], fe[3]); } else { unite(fe[3], fe[0]); unite(fe[1], fe[2]); }
                }
            }
        }
        int root_id[12];
        for (int e = 0; e < 12; e++) root_id[e] = -1;
        int k = 0;
        for (int e = 0; e < 12; e++) {
            if (!crossing[e]) continue;
            const int r = find(e);
            if (root_id[r] < 0) root_id[r] = k++;
            L.comp[e] = (int8_t)root_id[r];
        }
        L.ncomp = (uint8_t)k;
    }

    // Fine corner value at a point of a coarse cell given in half steps (0, 1, 2 per axis).
    double fine_value(const Leaf& L, int level, int hx, int hy, int hz, bool* found) const {
        const int shift = D_ - level;
        const uint64_t x = ((uint64_t)L.x << shift) + ((uint64_t)hx << (shift - 1));
        const uint64_t y = ((uint64_t)L.y << shift) + ((uint64_t)hy << (shift - 1));
        const uint64_t z = ((uint64_t)L.z << shift) + ((uint64_t)hz << (shift - 1));
        const uint64_t key = corner_key(x, y, z);
        auto it = std::lower_bound(ckeys_.begin(), ckeys_.end(), key);
        *found = it != ckeys_.end() && *it == key;
        return *found ? cval_[it - ckeys_.begin()] : 0.0;
    }
    double sample_at(const Leaf& L, int level, int axis, int side) const {
        int h[3] = {1, 1, 1};
        h[axis] = 2 * side;
        bool found;
        const double v = fine_value(L, level, h[0], h[1], h[2], &found);
        return found ? v : (L.f[0] < 0.0 ? -1.0 : 1.0);
    }

    // Bottom-up collapse.
    void collapse(AdaptiveStats& st) {
        for (int l = D_ - 1; l >= p_.min_depth; l--) {
            const Level& L = oct_.levels[l];
            for (uint32_t i = 0; i < L.cells.size(); i++) {
                const Cell& c = L.cells[i];
                if (p_.single_primitive_only && c.tree_n != 1) continue;
                // All children must be leaves (absent children are empty cells).
                bool ok = true;
                int present = 0;
                for (int k = 0; k < 8 && ok; k++) {
                    const int32_t ch = children_[l][i][k];
                    if (ch < 0) continue;
                    if (leaf_of_[l + 1][ch] < 0) ok = false;
                    present++;
                }
                if (!ok || present == 0) continue;
                Leaf merged;
                merged.x = c.x; merged.y = c.y; merged.z = c.z; merged.level = (uint8_t)l; merged.tree_n = c.tree_n;
                // Corner values of the node, from the fine corners.
                bool all_found = true;
                for (int k = 0; k < 8; k++) { bool found; merged.f[k] = fine_value(merged, l, 2 * (k & 1), 2 * ((k >> 1) & 1), 2 * ((k >> 2) & 1), &found); all_found = all_found && found; }
                if (!all_found) continue;
                // Topology: at most one crossing per edge (the midpoint agrees with an end), no
                // inner sheet in a face or in the cube whose corners share a sign, and one
                // component in the node and in every child.
                if (!topology_safe(merged, l)) continue;
                for (int k = 0; k < 8; k++) {
                    const int32_t ch = children_[l][i][k];
                    if (ch < 0) continue;
                    const Leaf& C = leaves_[leaf_of_[l + 1][ch]];
                    if (C.ncomp > 1) { ok = false; break; }
                }
                if (!ok) continue;
                Scratch sc;
                Counters dummy;
                components(merged, l, TreeView{}, sc, dummy);
                if (merged.ncomp != 1) continue;
                // Summed quadric of the children, one vertex, residual.
                adetail::Quadric Q;
                for (int k = 0; k < 8; k++) {
                    const int32_t ch = children_[l][i][k];
                    if (ch < 0) continue;
                    const Leaf& C = leaves_[leaf_of_[l + 1][ch]];
                    for (int q = 0; q < C.ncomp; q++) Q.add(quads_[leaf_of_[l + 1][ch]][q]);
                }
                if (Q.count < 3) continue;
                double lo[3], hi[3];
                cell_bounds(l, c.x, c.y, c.z, lo, hi);
                double residual = 0.0;
                Eigen::Vector3d x = Q.solve(lo, hi, &residual);
                const double cs = std::min(L.size[0], std::min(L.size[1], L.size[2]));
                if (residual > p_.tol * cs) continue;
                for (int a = 0; a < 3; a++) merged.v[0][a] = x[a];
                // Collapse: the children die, the node becomes a leaf.
                for (int k = 0; k < 8; k++) {
                    const int32_t ch = children_[l][i][k];
                    if (ch < 0) continue;
                    leaves_[leaf_of_[l + 1][ch]].alive = false;
                    leaf_of_[l + 1][ch] = -2;  // collapsed into the parent
                }
                leaf_of_[l][i] = (int32_t)leaves_.size();
                leaves_.push_back(merged);
                quads_.emplace_back();
                quads_.back()[0] = Q;
                st.collapsed++;
            }
        }
    }

    bool topology_safe(const Leaf& L, int level) const {
        // Samples at half steps: 27 points of the node from the fine corners.
        double s[3][3][3];
        for (int hx = 0; hx < 3; hx++) for (int hy = 0; hy < 3; hy++) for (int hz = 0; hz < 3; hz++) {
            bool found;
            const double v = fine_value(L, level, hx, hy, hz, &found);
            if (!found) {
                // A sample outside every leaf of the finest level: the region around it has no
                // surface, so its sign is that of any corner of its empty surroundings; use the
                // nearest node corner.
                s[hx][hy][hz] = L.f[(hx > 1 ? 1 : 0) | ((hy > 1 ? 1 : 0) << 1) | ((hz > 1 ? 1 : 0) << 2)];
            } else {
                s[hx][hy][hz] = v;
            }
        }
        auto in = [&](int x, int y, int z) { return s[x][y][z] < 0.0; };
        // Edges of the node: the midpoint must agree with an end.
        for (int e = 0; e < 12; e++) {
            const int c0 = adetail::edge_corners[e][0], c1 = adetail::edge_corners[e][1];
            const int a0[3] = {2 * (c0 & 1), 2 * ((c0 >> 1) & 1), 2 * ((c0 >> 2) & 1)}, a1[3] = {2 * (c1 & 1), 2 * ((c1 >> 1) & 1), 2 * ((c1 >> 2) & 1)};
            const int m[3] = {(a0[0] + a1[0]) / 2, (a0[1] + a1[1]) / 2, (a0[2] + a1[2]) / 2};
            const bool i0 = in(a0[0], a0[1], a0[2]), i1 = in(a1[0], a1[1], a1[2]), im = in(m[0], m[1], m[2]);
            if (im != i0 && im != i1) return false;
        }
        // Faces and the cube: if the corners share a sign, every sample must share it.
        for (int axis = 0; axis < 3; axis++) for (int side = 0; side < 2; side++) {
            bool first = true, sign = false, uniform = true;
            for (int u = 0; u < 3; u += 2) for (int v = 0; v < 3; v += 2) {
                int h[3]; h[axis] = 2 * side; h[(axis + 1) % 3] = u; h[(axis + 2) % 3] = v;
                const bool b = in(h[0], h[1], h[2]);
                if (first) { sign = b; first = false; } else if (b != sign) uniform = false;
            }
            if (!uniform) continue;
            for (int u = 0; u < 3; u++) for (int v = 0; v < 3; v++) {
                int h[3]; h[axis] = 2 * side; h[(axis + 1) % 3] = u; h[(axis + 2) % 3] = v;
                if (in(h[0], h[1], h[2]) != sign) return false;
            }
        }
        {
            bool first = true, sign = false, uniform = true;
            for (int k = 0; k < 8; k++) { const bool b = L.f[k] < 0.0; if (first) { sign = b; first = false; } else if (b != sign) uniform = false; }
            if (uniform) for (int hx = 0; hx < 3; hx++) for (int hy = 0; hy < 3; hy++) for (int hz = 0; hz < 3; hz++) if (in(hx, hy, hz) != sign) return false;
        }
        return true;
    }

    // ---------------------------------------------------------------- recursion of Ju et al.
    struct Ref { int level; int idx; };
    bool is_leaf(int level, int i) const { return leaf_of_[level][i] >= 0; }
    int child_of(int level, int i, int bx, int by, int bz) const { return children_[level][i][bx | (by << 1) | (bz << 2)]; }
    const Leaf& leaf(Ref r) const { return leaves_[leaf_of_[r.level][r.idx]]; }

    void cell_proc(int level, int i) {
        if (is_leaf(level, i)) return;
        for (int c = 0; c < 8; c++) if (children_[level][i][c] >= 0) cell_proc(level + 1, children_[level][i][c]);
        for (int axis = 0; axis < 3; axis++) {
            const int B = (axis + 1) % 3, C = (axis + 2) % 3;
            for (int pb = 0; pb < 2; pb++) for (int pc = 0; pc < 2; pc++) {
                int b0[3], b1[3];
                b0[axis] = 0; b0[B] = pb; b0[C] = pc;
                b1[axis] = 1; b1[B] = pb; b1[C] = pc;
                const int c0 = child_of(level, i, b0[0], b0[1], b0[2]), c1 = child_of(level, i, b1[0], b1[1], b1[2]);
                if (c0 >= 0 && c1 >= 0) face_proc(Ref{level + 1, c0}, Ref{level + 1, c1}, axis);
            }
            int first, second;
            adetail::others(axis, first, second);
            static const int pos[4][2] = {{0, 0}, {1, 0}, {1, 1}, {0, 1}};
            for (int h = 0; h < 2; h++) {
                Ref q[4];
                bool ok = true;
                for (int k = 0; k < 4; k++) {
                    int bits[3];
                    bits[axis] = h; bits[first] = pos[k][0]; bits[second] = pos[k][1];
                    const int c = child_of(level, i, bits[0], bits[1], bits[2]);
                    if (c < 0) { ok = false; break; }
                    q[k] = Ref{level + 1, c};
                }
                if (ok) edge_proc(q, axis);
            }
        }
    }

    void face_proc(Ref n0, Ref n1, int axis) {
        if (is_leaf(n0.level, n0.idx) && is_leaf(n1.level, n1.idx)) return;
        const int B = (axis + 1) % 3, C = (axis + 2) % 3;
        auto sub = [&](Ref n, int side, int pb, int pc, Ref& out) -> bool {
            if (is_leaf(n.level, n.idx)) { out = n; return true; }
            int bits[3];
            bits[axis] = side; bits[B] = pb; bits[C] = pc;
            const int c = child_of(n.level, n.idx, bits[0], bits[1], bits[2]);
            if (c < 0) return false;
            out = Ref{n.level + 1, c};
            return true;
        };
        for (int pb = 0; pb < 2; pb++) for (int pc = 0; pc < 2; pc++) {
            Ref s0, s1;
            if (sub(n0, 1, pb, pc, s0) && sub(n1, 0, pb, pc, s1)) face_proc(s0, s1, axis);
        }
        for (int sel = 0; sel < 2; sel++) {
            const int e_axis = sel == 0 ? B : C, across = sel == 0 ? C : B;
            int first, second;
            adetail::others(e_axis, first, second);
            static const int pos[4][2] = {{0, 0}, {1, 0}, {1, 1}, {0, 1}};
            for (int h = 0; h < 2; h++) {
                Ref q[4];
                bool ok = true;
                for (int k = 0; k < 4; k++) {
                    int side_bit, across_bit;
                    if (first == axis) { side_bit = pos[k][0]; across_bit = pos[k][1]; } else { across_bit = pos[k][0]; side_bit = pos[k][1]; }
                    const Ref n = side_bit == 0 ? n0 : n1;
                    if (is_leaf(n.level, n.idx)) { q[k] = n; continue; }
                    int bits[3];
                    bits[axis] = side_bit == 0 ? 1 : 0; bits[e_axis] = h; bits[across] = across_bit;
                    const int c = child_of(n.level, n.idx, bits[0], bits[1], bits[2]);
                    if (c < 0) { ok = false; break; }
                    q[k] = Ref{n.level + 1, c};
                }
                if (ok) edge_proc(q, e_axis);
            }
        }
    }

    void edge_proc(const Ref q[4], int axis) {
        bool all_leaves = true;
        for (int k = 0; k < 4; k++) all_leaves = all_leaves && is_leaf(q[k].level, q[k].idx);
        if (all_leaves) { process_edge(q, axis); return; }
        int first, second;
        adetail::others(axis, first, second);
        static const int pos[4][2] = {{0, 0}, {1, 0}, {1, 1}, {0, 1}};
        for (int h = 0; h < 2; h++) {
            Ref s[4];
            bool ok = true;
            for (int k = 0; k < 4; k++) {
                if (is_leaf(q[k].level, q[k].idx)) { s[k] = q[k]; continue; }
                int bits[3];
                bits[axis] = h; bits[first] = 1 - pos[k][0]; bits[second] = 1 - pos[k][1];
                const int c = child_of(q[k].level, q[k].idx, bits[0], bits[1], bits[2]);
                if (c < 0) { ok = false; break; }
                s[k] = Ref{q[k].level + 1, c};
            }
            if (ok) edge_proc(s, axis);
        }
    }

    void process_edge(const Ref q[4], int axis) {
        int first, second;
        adetail::others(axis, first, second);
        static const int pos[4][2] = {{0, 0}, {1, 0}, {1, 1}, {0, 1}};
        int deepest = 0;
        for (int k = 1; k < 4; k++) if (q[k].level > q[deepest].level) deepest = k;
        int lidx[4];
        for (int k = 0; k < 4; k++) {
            int bits[3] = {0, 0, 0};
            bits[first] = 1 - pos[k][0]; bits[second] = 1 - pos[k][1];
            lidx[k] = adetail::local_edge(axis, bits[0], bits[1], bits[2]);
        }
        const Leaf& Ld = leaf(q[deepest]);
        const int e = lidx[deepest];
        const double f0 = Ld.f[adetail::edge_corners[e][0]], f1 = Ld.f[adetail::edge_corners[e][1]];
        if ((f0 < 0.0) == (f1 < 0.0)) return;
        uint32_t v[4];
        for (int k = 0; k < 4; k++) {
            const Leaf& L = leaf(q[k]);
            if (L.ncomp == 0) return;
            int c = L.comp[lidx[k]];
            if (c < 0) c = 0;
            v[k] = vbase_[leaf_of_[q[k].level][q[k].idx]] + (uint32_t)c;
        }
        uint32_t u[4];
        int m = 0;
        for (int k = 0; k < 4; k++) if (m == 0 || u[m - 1] != v[k]) u[m++] = v[k];
        if (m == 4 && u[3] == u[0]) m = 3;
        if (m < 3) return;
        if (m == 3) {
            if (f0 >= 0.0) std::swap(u[1], u[2]);
            mesh_.F.insert(mesh_.F.end(), {u[0], u[1], u[2]});
            return;
        }
        if (f0 >= 0.0) std::swap(v[1], v[3]);
        mesh_.F.insert(mesh_.F.end(), {v[0], v[1], v[2], v[0], v[2], v[3]});
    }
};

inline Mesh adaptive_mesh(const Scene& scene, const AdaptiveParams& ap, const DCParams& dp, Counters& counters, AdaptiveStats& st) {
    AdaptiveMesher m(scene, ap, dp);
    return m.run(counters, st);
}

}  // namespace lpm
